#!/usr/bin/env python3
"""Synthetic "no-cue" sentences (dev only, generated by the team, no real data).

Names appear WITHOUT the cues our rules know (no "Name:", no S/o, no ji/sahab, no
"called by", not in any registration table). Capitalised medical words appear as decoys.
TRAIN and TEST use disjoint templates AND disjoint name pools, so the test is blind.

Each item: (sentence, [name strings that must be removed], [decoys that must stay]).
"""
from __future__ import annotations

import random

FIRST_TRAIN = ["Ramesh", "Sunita", "Anil", "Kavya", "Deepak", "Pooja", "Vikram", "Anjali", "Suresh", "Neelam",
               "Rakesh", "Shabana", "Imran", "Farzana", "Gurpreet", "Harjeet", "Lakshmi", "Murugan", "Sanjay",
               "Rekha", "Ajit", "Babita", "Dinesh", "Geeta", "Hemant", "Jyoti", "Mahesh", "Nirmala", "Pankaj",
               "Rubina", "Salim", "Tara", "Umesh", "Vandana", "Yusuf", "Zeenat", "Aslam", "Bhavna", "Chandan", "Divya"]
LAST_TRAIN = ["Yadav", "Verma", "Gupta", "Singh", "Khan", "Ansari", "Mishra", "Tiwari", "Pandey", "Chauhan",
              "Kushwaha", "Maurya", "Nishad", "Paswan", "Rawat", "Saxena", "Srivastava", "Thakur", "Qureshi", "Siddiqui"]
FIRST_TEST = ["Ramprasad", "Shabnam", "Kuldeep", "Meenakshi", "Arvind", "Nasreen", "Bholanath", "Sarla", "Tejpal",
              "Kamini", "Lalit", "Mehrunisa", "Omkar", "Pushpa", "Raghav", "Sushila", "Ishwar", "Gulnaz", "Jatin",
              "Hemlata", "Navin", "Phoolmati", "Rizwan", "Sheela", "Trilok", "Urmila", "Vinod", "Waseem", "Yamuna", "Zubair"]
LAST_TEST = ["Kashyap", "Lodhi", "Rajbhar", "Sonkar", "Prajapati", "Bind", "Kurmi", "Jaiswal", "Agrahari",
             "Dubey", "Shukla", "Bajpai", "Usmani", "Rizvi", "Kesarwani"]
# decoys are DISJOINT between train and test (otherwise the model could learn test drug endings)
DECOYS_TRAIN = ["Paracetamol", "Amlodipine", "Metformin", "Pantoprazole", "Ceftriaxone", "Azithromycin", "Dengue",
                "Malaria", "Cardiology", "Medicine", "Haemoglobin", "Ondansetron", "Cefixime", "Losartan",
                "Diclofenac", "Ibuprofen", "Cetirizine", "Omeprazole", "Glimepiride", "Hepatitis", "Nephrology",
                "Orthopaedics", "Chikungunya", "Amoxicillin", "Furosemide"]
DECOYS_TEST = ["Insulin", "Typhoid", "Tuberculosis", "Surgery", "Doxycycline", "Ranitidine", "Telmisartan",
               "Atorvastatin", "Levothyroxine", "Montelukast", "Clopidogrel", "Pneumonia", "Gastroenterology",
               "Prednisolone", "Salbutamol"]
# ordinary capitalised words at the start of a sentence (train only)
COMMON_START_TRAIN = ["Sample", "Report", "Plan", "Advice", "Review", "Repeat", "Continue", "Started", "Stopped",
                      "Monitor", "Check", "Keep", "Shift", "Send", "Collect", "Discussed", "Explained", "Noted",
                      "Patient", "Blood", "Urine", "Fever", "Pain", "Dressing", "Diet", "Ward", "Night", "Morning"]
NEG_TEMPLATES_TRAIN = [
    "{W} received from the lab, {D} started.",
    "{W} sent for culture, {D} to continue.",
    "Patient ko {D} di gayi, {W} normal hai.",
    "{D} ko band kar diya, {W} kal karenge.",
    "{W} done at noon; {D} given as advised.",
    "{D} ne kaam kiya, bukhar utar gaya.",
    "{W} reviewed, no change in {D}.",
    "Mareez ko {D} se aaram mila.",
]

TRAIN_TEMPLATES = [
    "Discussed the plan with {N} today; {D} continued.",
    "{N} was reviewed in the evening, tolerating {D} well.",
    "Explained the reports to {N} and the family.",
    "{N} refused the {D} dose at night.",
    "Phone call from {N} regarding discharge papers.",
    "{N} aaj OPD mein aaye the, {D} di gayi.",
    "{N} ki tabiyat theek hai, {D} chalu rakhein.",
    "Raat ko {N} ne {D} li, neend achhi aayi.",
    "{N} ka sugar high tha, {D} badhaya.",
    "Subah {N} ko halka bukhar tha.",
    "Counselled {N} about diet and {D}.",
    "{N} complained of pain after {D}.",
    "Handed over {N} to the night staff.",
    "{N} se baat hui, kal follow up.",
    "Reports collected by {N} from the lab.",
]
TEST_TEMPLATES = [
    "Spoke with {N} about the discharge; {D} to continue.",
    "Kal {N} aayi thi, BP check kiya.",
    "{N} has been on {D} since Monday.",
    "Met {N} in the corridor, explained the {D} schedule.",
    "{N} ne bataya ki {D} se ulti ho rahi hai.",
    "As per {N}, the pain started two days ago.",
    "{N} wanted to know when {D} can be stopped.",
    "Shaam ko {N} ki report aa gayi.",
    "{N} is anxious about the {D} injection.",
    "Follow-up advised; {N} will come on Friday.",
    "{N} ko {D} ke baad aaram mila.",
    "Informed {N} that {D} is available in the pharmacy.",
]


def _name(rnd, firsts, lasts):
    return rnd.choice(firsts) if rnd.random() < 0.35 else f"{rnd.choice(firsts)} {rnd.choice(lasts)}"


def generate(split: str, n: int, seed: int = 11):
    rnd = random.Random(f"{split}-{seed}")
    templates = TRAIN_TEMPLATES if split == "train" else TEST_TEMPLATES
    firsts, lasts = (FIRST_TRAIN, LAST_TRAIN) if split == "train" else (FIRST_TEST, LAST_TEST)
    decoys = DECOYS_TRAIN if split == "train" else DECOYS_TEST
    out = []
    for _ in range(n):
        t = rnd.choice(templates)
        name = _name(rnd, firsts, lasts)
        decoy = rnd.choice(decoys)
        out.append((t.format(N=name, D=decoy), [name], [decoy] if "{D}" in t else []))
    if split == "train":                              # hard negatives: no names at all
        for _ in range(n // 2):
            t = rnd.choice(NEG_TEMPLATES_TRAIN)
            out.append((t.format(W=rnd.choice(COMMON_START_TRAIN), D=rnd.choice(decoys)), [], []))
    return out


if __name__ == "__main__":
    for s, names, decoys in generate("test", 5):
        print(s, names, decoys)
